const items = $input.all();

return items.map((item) => {
  const output = item.json.output;
  const errors = [];
  const warnings = [];

  const draftLabel = "UNAPPROVED — DRAFT ONLY";

  const rawText =
    typeof output === "string" ? output.trim() : "";

  if (!rawText) {
    errors.push("AI output is missing or empty.");
  }

  // Normalize draft label for display.
  // Preserve the original output for validation.
  let text = rawText;

  if (!text.startsWith(draftLabel)) {
    text = `${draftLabel}\n\n${text}`;
  }

  if (!text.endsWith(draftLabel)) {
    text = `${text}\n\n${draftLabel}`;
  }

  const upper = rawText.toUpperCase();

  // 1. Check required proposal sections
  const requiredSections = [
    "CAMPAIGN BRIEF",
    "AUDIENCE SELECTION",
    "DRAFT EMAIL",
    "RISKS, ASSUMPTIONS AND VALIDATION CHECKS"
  ];

  for (const section of requiredSections) {
    if (!upper.includes(section)) {
      errors.push(`Missing section: ${section}`);
    }
  }

  // 2. Check original draft-only labels
  if (
    !rawText.startsWith(draftLabel) ||
    !rawText.endsWith(draftLabel)
  ) {
    warnings.push(
      "AI omitted a required draft label. " +
      "The display copy was normalized; human review is required."
    );
  }

  // 3. Detect generated SQL
  const sqlPattern =
    /```sql\b|\bSELECT\b[\s\S]{0,300}\bFROM\b|\bINSERT INTO\b|\bUPDATE\s+\w+\s+SET\b|\bDELETE FROM\b|\bDROP TABLE\b/i;

  if (sqlPattern.test(rawText)) {
    errors.push(
      "Generated SQL detected. Use sql/audience.sql instead."
    );
  }

  // 4. Require reference to existing audience SQL
  if (!rawText.includes("sql/audience.sql")) {
    errors.push(
      "Missing reference to existing audience SQL."
    );
  }

  // 5. Require human approval
  if (
    !/CRM manager.{0,60}approv|approv.{0,60}CRM manager/i.test(rawText)
  ) {
    errors.push(
      "Mandatory CRM manager approval not stated."
    );
  }

  // 6. Detect unsupported marketing claims
  const unsupportedClaims = [
    /\bnew vehicle listings\b/i,
    /\blatest used vehicles\b/i,
    /\bcompetitive pricing\b/i,
    /\bspecial offers?\b/i,
    /\bdiscounts?\b/i,
    /\bincentives?\b/i,
    /\bupcoming events\b/i,
    /\bexclusive deals?\b/i,
    /\bnew arrivals\b/i
  ];

  if (unsupportedClaims.some((pattern) => pattern.test(rawText))) {
    errors.push(
      "Potential unsupported marketing claims detected. " +
      "Remove or substantiate before human review."
    );
  }

  // 7. Detect misleading validation claims
  const misleadingClaims = [
    /\bconsent has been verified\b/i,
    /\beligibility has been verified\b/i,
    /\baudience has been approved\b/i,
    /\bSQL has been executed\b/i
  ];

  if (misleadingClaims.some((pattern) => pattern.test(rawText))) {
    errors.push(
      "Unsupported claim of completed verification or approval."
    );
  }

  // 8. Additional review requirements
  warnings.push(
    "Customer eligibility, consent, inactivity, suppression " +
    "and deduplication have NOT been independently verified " +
    "by this node."
  );

  warnings.push(
    "The existing sql/audience.sql must be executed and " +
    "checked separately before campaign activation."
  );

  // 9. Final validation result
  const passed = errors.length === 0;

  return {
    json: {
      campaign_proposal: text,
      validation_status: passed ? "PASS" : "FAIL",
      ready_for_human_review: passed,
      errors,
      warnings,
      audience_sql_reference: "sql/audience.sql",
      audience_eligibility_verified: false,
      campaign_approved: false,
      campaign_sent: false
    }
  };
});
